class Solution {
public:
    int getMinDistance(vector<int>& nums, int target, int start) {
        int ans = INT_MAX;
        int n = (int)nums.size();
        for (int i = 0; i < n; i++) {
            if (nums[i] == target) {
                int d = i - start;
                if (d < 0) d = -d;
                if (d < ans) ans = d;
            }
        }
        return ans;
    }
};
